import { findTournamentParticipant } from '../../acquire/findTournamentParticipant.mjs';
import { requireParams } from '../../helpers/parameters/requireParams.mjs';
import { getTimeItem } from '../base/timeItems.mjs';
import { PAYMENT_STATUS, paymentStatusValues } from '../../constants/participantConstants.mjs';
import { TOURNAMENT_RECORD, PARTICIPANT_ID } from '../../constants/attributeConstants.mjs';
import { PARTICIPANT_NOT_FOUND } from '../../constants/errorConditionConstants.mjs';

function getParticipantPaymentStatus({ tournamentRecord, participantId }) {
    const paramsCheck = requireParams({ tournamentRecord, participantId }, [TOURNAMENT_RECORD, PARTICIPANT_ID]);
    if (paramsCheck.error)
        return paramsCheck;
    const { participant } = findTournamentParticipant({
        tournamentRecord,
        participantId,
    });
    if (!participant)
        return { error: PARTICIPANT_NOT_FOUND };
    const { timeItem } = getTimeItem({
        itemType: PAYMENT_STATUS,
        element: participant,
    });
    if (timeItem && paymentStatusValues.includes(timeItem.itemValue)) {
        return timeItem.itemValue;
    }
    return undefined;
}

