import { modifyParticipantsNotice } from '../notifications/participantNotifications.mjs';
import { addParticipantPresenceAttestation } from '../timeItems/addTimeItem.mjs';
import { validatePresenceAttribution } from '../../query/participant/presencePolicy.mjs';
import { buildAttestation } from '../presence/buildAttestation.mjs';
import { latestPresenceState } from '../../acquire/presenceAttestations.mjs';
import { requireParams } from '../../helpers/parameters/requireParams.mjs';
import { getParticipantId } from '../../functions/global/extractors.mjs';
import { getTopics } from '../../global/state/globalState.mjs';
import { nowIso } from '../../tools/clock.mjs';
import { SIGNED_IN, SIGNED_OUT } from '../../constants/participantConstants.mjs';
import { TOURNAMENT_RECORD } from '../../constants/attributeConstants.mjs';
import { MODIFY_PARTICIPANTS } from '../../constants/topicConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';
import { MISSING_VALUE, INVALID_VALUES, MISSING_PARTICIPANTS, INVALID_ATTRIBUTION } from '../../constants/errorConditionConstants.mjs';

function modifyParticipantsSignInStatus({ tournamentRecord, participantIds, attributedTo, signInState, occurredAt, notes, }) {
    const paramsCheck = requireParams({ tournamentRecord }, [TOURNAMENT_RECORD]);
    if (paramsCheck.error)
        return paramsCheck;
    if (!Array.isArray(participantIds))
        return { error: MISSING_VALUE };
    const validSignInState = [SIGNED_IN, SIGNED_OUT].includes(signInState);
    if (!validSignInState)
        return { error: INVALID_VALUES, signInState };
    const participants = tournamentRecord.participants ?? [];
    if (!participants.length)
        return { error: MISSING_PARTICIPANTS };
    const allParticipantIds = new Set(participants.map(getParticipantId));
    const invalidParticipantIds = participantIds.filter((participantId) => !allParticipantIds.has(participantId));
    if (invalidParticipantIds.length)
        return { error: INVALID_VALUES, context: { invalidParticipantIds } };
    const modifiedParticipants = [];
    const batchOccurredAt = occurredAt ?? nowIso();
    for (const participant of participants) {
        const { participantId } = participant;
        if (!participantIds.includes(participantId))
            continue;
        if (latestPresenceState(participant) === signInState) {
            modifiedParticipants.push(participant);
            continue;
        }
        const attribution = validatePresenceAttribution({
            fact: 'signIn',
            tournamentRecord,
            attributedTo,
            participant,
        });
        if (!attribution.valid && attribution.onInvalid === 'reject') {
            return { error: INVALID_ATTRIBUTION, context: { participantId, reason: attribution.reason } };
        }
        const result = addParticipantPresenceAttestation({
            attestation: buildAttestation({
                occurredAt: batchOccurredAt,
                state: signInState,
                participantId,
                attributedTo,
                notes,
            }),
            disableNotice: true,
            tournamentRecord,
            participantId,
        });
        if (result.error)
            return result;
        modifiedParticipants.push(participant);
    }
    const { topics } = getTopics();
    if (modifiedParticipants.length && topics.includes(MODIFY_PARTICIPANTS)) {
        modifyParticipantsNotice({
            tournamentId: tournamentRecord.tournamentId,
            participants: modifiedParticipants,
        });
    }
    return { ...SUCCESS };
}

export { modifyParticipantsSignInStatus };
