import { setFirstClassOrExtension } from '../extensions/setFirstClassOrExtension.mjs';
import { modifyEventNotice } from '../notifications/eventNotifications.mjs';
import { requireParams } from '../../helpers/parameters/requireParams.mjs';
import { getFlightProfile } from '../../query/event/getFlightProfile.mjs';
import { deleteDrawDefinitions } from './deleteDrawDefinitions.mjs';
import { TOURNAMENT_RECORD, EVENT } from '../../constants/attributeConstants.mjs';
import { FLIGHT_PROFILE } from '../../constants/extensionConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';

function deleteFlightProfileAndFlightDraws({ autoPublish = true, tournamentRecord, auditData, event, force }) {
    const paramsCheck = requireParams({ tournamentRecord, event }, [TOURNAMENT_RECORD, EVENT]);
    if (paramsCheck.error)
        return paramsCheck;
    const { flightProfile } = getFlightProfile({ event });
    if (flightProfile) {
        const drawIds = flightProfile.flights?.map(({ drawId }) => drawId).filter(Boolean);
        const result = deleteDrawDefinitions({
            eventId: event.eventId,
            tournamentRecord,
            autoPublish,
            auditData,
            drawIds,
            event,
            force,
        });
        if (result.error)
            return result;
        const removal = setFirstClassOrExtension({
            element: event,
            attribute: 'flightProfile',
            name: FLIGHT_PROFILE,
            value: undefined,
        });
        if (!removal.error)
            modifyEventNotice({ tournamentId: tournamentRecord.tournamentId, event });
        return removal;
    }
    return { ...SUCCESS };
}

export { deleteFlightProfileAndFlightDraws };
