function checkDependenciesScheduled({ matchUpScheduleTimes, matchUpDependencies, allDateMatchUpIds, matchUp }) {
    const matchUpIdDependencies = (matchUpDependencies?.[matchUp.matchUpId]?.matchUpIds ?? []).filter((matchUpId) => allDateMatchUpIds.includes(matchUpId));
    const remainingDependencies = matchUpIdDependencies.filter((matchUpId) => !matchUpScheduleTimes[matchUpId]);
    const dependenciesScheduled = !remainingDependencies?.length;
    return { dependenciesScheduled, remainingDependencies };
}

export { checkDependenciesScheduled };
