import { MISSING_OFFICIAL_RECORD, MISSING_EVALUATION_POLICY } from '../../constants/officiatingConstants.mjs';
import { INVALID_VALUES } from '../../constants/errorConditionConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';

function getEvaluationTemplate({ officialRecord, policyName, evaluationPolicy }) {
    let policy = evaluationPolicy;
    if (!policy && policyName) {
        if (!officialRecord)
            return { error: MISSING_OFFICIAL_RECORD };
        policy = officialRecord.evaluationPolicies.find((p) => p.policyName === policyName);
    }
    if (!policy) {
        if (policyName)
            return { error: MISSING_EVALUATION_POLICY, context: { policyName } };
        return { error: INVALID_VALUES, context: { message: 'Missing evaluationPolicy or policyName' } };
    }
    const fields = [];
    for (const section of policy.sections) {
        for (const criterion of section.criteria) {
            fields.push({
                fieldId: `${section.sectionId}.${criterion.criterionId}`,
                sectionId: section.sectionId,
                sectionName: section.sectionName,
                criterionId: criterion.criterionId,
                criterionName: criterion.criterionName,
                description: criterion.description,
                scoringType: criterion.scoringType,
                scaleOptions: criterion.scaleOptions,
                numericRange: criterion.numericRange,
                required: criterion.required,
                weight: criterion.weight,
                sectionWeight: section.weight,
            });
        }
    }
    return { ...SUCCESS, fields, evaluationPolicy: policy };
}

export { getEvaluationTemplate };
